import urllib.request
for strategy, segment in [('1','/_tree'), ('1','/product/__PAGE__'), ('3',None), ('2',None)]:
 h={'RSC':'1','Next-Router-Prefetch':strategy}
 if segment: h['Next-Router-Segment-Prefetch']=segment
 req=urllib.request.Request('http://localhost:3100/product',headers=h)
 try:
  with urllib.request.urlopen(req) as resp:
   data=resp.read()
   print(strategy,segment,resp.status,resp.headers.get('content-type'),len(data),b'Compact Widget' in data,b'Loading related products' in data,resp.headers.get('x-nextjs-cache'))
